{
  "sections": [
    {"key":"verdict","title":"निष्कर्ष","text":"आपका प्रोजेक्ट वित्तीय रूप से व्यवहार्य है। डिएससीआर {{min_dscr}} और पेबैक अवधि {{payback_months}} महीने दोनों ही अनुकूल हैं।"},
    {"key":"market","title":"बाजार","text":"गाँव में अनुमानित घरों की संख्या {{households}} है। वर्तमान में कोई निकटवर्ती प्रतिस्पर्धी नहीं है, इसलिए बाजार में अवसर बड़ा है। आप सीधे घरों को या सहकारी केंद्र के माध्यम से दूध बेच सकते हैं।"},
    {"key":"pricing","title":"मूल्य निर्धारण","text":"दूध की कीमत स्थानीय बाजार में प्रतिस्पर्धी है। आपके उत्पादन क्षमता के आधार पर आप उचित लाभ मार्जिन रख सकते हैं। लागत में मुख्य आइटम {{cost.animals}} (बफ़ेलो) और {{cost.shed}} (पशु शेड) हैं।"},
    {"key":"risks","title":"जोखिम","text":"बफ़ेलो की स्वास्थ्य समस्याएँ, मौसम का प्रभाव, और संभावित प्रतिस्पर्धा भविष्य में आ सकते हैं। नकदी प्रवाह में अचानक गिरावट या ब्याज दर में बदलाव भी जोखिम हो सकते हैं।"},
    {"key":"path_to_yes","title":"पाथ टू यीएस","text":"बधाई हो! आपका प्रोजेक्ट पहले से ही स्वीकृत है, कोई अतिरिक्त बदलाव आवश्यक नहीं है।"},
    {"key":"next_steps","title":"आगे के कदम","text":"PMEGP योजना के तहत सब्सिडी और ऋण के लिए आवेदन करें, बफ़ेलो खरीदें, शेड बनवाएँ, और स्थानीय बाजार में बिक्री चैनल स्थापित करें। नियमित रूप से वित्तीय रिकॉर्ड रखें और उत्पादन की गुणवत्ता बनाए रखें।"}
  ],
  "swot": {
